mapper.select:
SELECT 
FROM diet_meal
WHERE tenant_id = #{tenantId}
  AND people_id = #{peopleId}
  AND meal_date >= #{from}
  AND meal_date <= #{to}
  AND is_deleted = 0
ORDER BY meal_date ASC,
         FIELD(meal_type, 'BREAKFAST', 'LUNCH', 'DINNER', 'SNACK'),
         eaten_at ASC,
         gmt_created ASC
